RECORD = 6  # bytes of the game's control record: one seat's input for one step
INPUT_SLOT = 8  # bytes one seat's record takes in the input buffer (a 6-byte record in an 8-byte place)
RING_STEPS = 1024  # steps the input buffer and the checksum ring keep: step s is at s & 1023
LAPS_MIN = 0  # the fewest laps the game takes: 0 is a free run, with no lap count
LAPS_MAX = 99  # the most laps the game takes: two digits, as its lap counter shows
CPU_LEVEL_MAX = 3  # the highest CPU level: 0 Novice, 1 Standard, 2 Expert, 3 Master
SETTING_MAX = 100  # the highest machine setting: 0 is all acceleration, 100 all top speed
FINISH_LIMIT_MAX = 600  # the longest a host may set between the first finish and the race's end for everyone, in seconds (0: no such end)
MINE_REGEN_MAX = 5000  # the longest a host may set between a mine going off and its coming back, in milliseconds (0: a mine stays gone, the game's own way)
MINE_REGEN_STEP = 50  # the host's mine rule moves in steps of this many milliseconds: 50 ms is 3 steps of the game exactly
INPUT_DELAY = 2  # steps between a player's input and the step it is used in (decided: 2, never more)
MAX_UNTRACKED = 32  # memory ranges never rolled back, at most (the list at UNTRACKED)

